19	// Both real signals this component reads on mount — `navigator.languages` and the
20	// `zimm-region-pref` cookie — are deliberately NOT props (see index.tsx's own doc comment: this
21	// container takes only `{site, locale, buildUrl}`, matching what `_app` already has in scope), so
22	// they can't be seeded via a Storybook arg the normal way. Each story below sets both directly,
23	// synchronously, in its own wrapper component's *render body* — not inside a `useEffect`. React
24	// flushes a newly-mounted tree's effects bottom-up (children before parents), so a wrapper-level
25	// `useEffect` would run *after* ZimmLanguagePrompt's own eligibility-check effect has already read
26	// whatever value was there beforehand. Setting both during render guarantees they're in place
27	// before anything in the tree mounts.
28	
29	const SITE = { id: 'ZimmermannEUit', sfccSiteId: 'ZimmermannEU' };
30	const LOCALE = { id: 'it' };
31	const BUILD_URL = (path: string): string => path;
32	
33	/**
34	 * Overrides `navigator.languages` by defining a fresh own-property directly on the `navigator`
35	 * instance, shadowing `Navigator.prototype`'s own getter — the standard technique for overriding
36	 * `navigator.*` in a real browser context (used the same way by browser automation tools). This
37	 * does not require the prototype's own accessor to be configurable, since it adds a new property
38	 * on the instance rather than redefining the prototype's.
39	 */
40	const setBrowserLanguages = (languages: readonly string[]): void => {
41	  Object.defineProperty(window.navigator, 'languages', {
42	    value: languages,
43	    configurable: true,
44	  });
45	};
46	
47	/** Clears the cookie directly — `regionPrefCookie.ts`'s `setRegionPrefCookie(value)`
48	 *  (`regionPrefCookie.ts:158-168`) writes exactly the object it's given straight to
49	 *  `document.cookie` (the assignment itself is line 164), with no merge/clear form, so there is
50	 *  no exported helper to reach for here. An expired `max-age=0` removes the cookie outright. */
51	const clearRegionPrefCookie = (): void => {
52	  document.cookie = `${COOKIE_NAME}=; path=/; max-age=0`;
53	};
54	
55	// Storybook reuses one preview iframe across story navigations within a session (no full page
56	// reload per story), so overriding `navigator.languages`/the cookie without restoring them would
57	// leak into whichever *other* story renders next, if that story happens to read either — capture
58	// the true original once per mount (via useState's lazy initializer, so a later re-render can't
59	// recapture an already-overridden value) and restore both on unmount. The restore itself must be
60	// the effect's *cleanup*, not its body — the body would just reapply the override, and per the
61	// comment above, this file's whole seeding technique already depends on that override happening
62	// synchronously during render, not inside an effect.
63	const useRestoreBrowserLanguagesOnUnmount = (): ((languages: readonly string[]) => void) => {
64	  const [originalLanguages] = useState(() => window.navigator.languages);
65	  useEffect(() => {
66	    return () => {
67	      setBrowserLanguages(originalLanguages);
68	      clearRegionPrefCookie();
69	    };
70	  }, [originalLanguages]);
71	  return setBrowserLanguages;
72	};
