          <div className="[text-box-edge:cap_alphabetic] [text-box-trim:trim-both] [word-break:break-word] flex flex-col font-[family-name:var(--brand\/font\/family\/body,'Futura_Round:medium')] font-[var(--brand\/font\/weight\/bold,normal)] justify-center leading-[0] relative shrink-0 text-[color:var(--alias\/color\/action\/primary\/text\/default,white)] text-[length:var(--brand\/font\/size\/300,12px)] text-center uppercase whitespace-nowrap" data-node-id="I40002218:79877;40002218:79446;40000196:1463">
            <p className="leading-[var(--brand\/font\/lineheight\/450,18px)]">STAY ON UK STORE</p>
          </div>
        </div>
      </div>
    </div>
  );
}

