1	import React, { type CSSProperties } from 'react';
2	import { Button as ChakraButton, IconButton, chakra, useStyleConfig, type SystemStyleObject } from '@chakra-ui/react';
3	import { ZimmIcon } from '../zimmIcon';
4	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
5	
6	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
7	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
8	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
9	
10	type ZimmButtonBaseProps = {
11	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
12	  label: string;
13	  type?: 'button' | 'submit' | 'reset';
14	  disabled?: boolean;
15	  /**
16	   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
17	   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
18	   * reader users can never reach it to hear why the action is unavailable. `onClick` is
19	   * suppressed here rather than by the DOM. Prefer this over `disabled` for
20	   * unavailable-but-explainable states (e.g. Add to Bag with an out-of-stock size selected).
21	   *
22	   * No recipe change is needed: Chakra's `_disabled` pseudo already expands to
23	   * `&:disabled, &[disabled], &[aria-disabled=true], &[data-disabled]`.
24	   */
25	  ariaDisabled?: boolean;
26	  inverse?: boolean;
27	  onClick?: () => void;
28	  style?: CSSProperties;
29	  /** Chakra `sx` passthrough — for a caller-owned recipe part, not a one-off inline style. */
30	  sx?: SystemStyleObject;
31	};
32	
33	type ZimmLabelButtonProps = ZimmButtonBaseProps & {
34	  variant?: 'primary' | 'secondary' | 'social';
35	  /** 'large' = 52px fixed · 'medium' = 40px fixed · 'adaptive' = 40px mobile → 52px desktop
36	   *  (same responsive size as the social variant, applied to primary/secondary colours). */
37	  size?: 'large' | 'medium' | 'adaptive';
38	  fullWidth?: boolean;
39	  /** Links an explanatory message element by id so screen readers announce it on focus. */
40	  ariaDescribedBy?: string;
41	  /** Optional icon rendered before the label. Pass a ZimmIcon or any React node. */
42	  iconLeading?: React.ReactNode;
43	  /** Optional icon rendered after the label. Pass a ZimmIcon or any React node. */
44	  iconTrailing?: React.ReactNode;
45	};
46	
47	type ZimmIconButtonProps = ZimmButtonBaseProps & {
48	  variant: 'icon';
49	  icon: ZimmIconType;
50	  /** Icon render size — one of the iconSizes keys ('sm' | 'md' | 'lg'). Defaults to 'md' (16px). */
51	  size?: ZimmIconSize;
52	};
53	
54	type ZimmButtonProps = ZimmLabelButtonProps | ZimmIconButtonProps;
55	
56	const ICON_SIZE_DEFAULT: ZimmIconSize = 'md';
57	
58	/** Atom — labelled button (primary/secondary) or icon-only button. All visual states
59	 *  are handled by `zimmButton.css.ts` (co-located beside this file) — no React state for hover/press/focus.
60	 *  Labelled variants accept optional `iconLeading` and `iconTrailing` nodes rendered either
61	 *  side of the label; gap between icon and text is set by the button's flex gap in baseStyle. */
62	export const ZimmButton = (props: ZimmButtonProps) => {
63	  const { label, type = 'button', disabled = false, ariaDisabled = false, inverse = false, onClick, style, sx } = props;
64	  // aria-disabled leaves the button clickable at the DOM level, so the no-op has to happen here.
65	  const handleClick = ariaDisabled ? undefined : onClick;
66	  const ariaDisabledAttr = ariaDisabled || undefined;
67	  const labelStyle = useStyleConfig('ZimmButtonLabel', {});
68	
69	  if (props.variant === 'icon') {
70	    return (
71	      <IconButton
72	        aria-label={label}
73	        type={ariaDisabled ? 'button' : type}
74	        isDisabled={disabled}
75	        aria-disabled={ariaDisabledAttr}
76	        onClick={handleClick}
77	        variant={inverse ? 'iconInverse' : 'icon'}
78	        size="icon"
79	        icon={<ZimmIcon type={props.icon} size={props.size ?? ICON_SIZE_DEFAULT} aria-hidden={true} />}
80	        style={style}
81	        sx={sx}
82	      />
83	    );
84	  }
85	
86	  const variant = props.variant ?? 'primary';
87	  // social → 'social' Chakra size; adaptive → reuses the same 'social' size entry (same
88	  // responsive height/padding tokens, different variant colours); large → 'lg'; medium → 'sm'.
89	  const size = variant === 'social' || props.size === 'adaptive' ? 'social' : props.size === 'medium' ? 'sm' : 'lg';
90	  // Maps inverse prop to the *Inverse variant suffix defined in zimmButton.css.ts.
91	  // inverse has no effect on the social variant (no socialInverse exists in the theme).
92	  const chakraVariant = variant === 'social' ? 'social' : `${variant}${inverse ? 'Inverse' : ''}`;
93	  const ariaDescribedBy = 'ariaDescribedBy' in props ? props.ariaDescribedBy : undefined;
94	
95	  return (
96	    <ChakraButton
97	      type={ariaDisabled ? 'button' : type}
98	      isDisabled={disabled}
99	      aria-disabled={ariaDisabledAttr}
100	      // aria-label makes the accessible name explicit so VoiceOver doesn't read
101	      // CSS text-transform:uppercase as an acronym (e.g. "A-D-D to bag").
102	      aria-label={label}
103	      aria-describedby={ariaDescribedBy}
104	      onClick={handleClick}
105	      variant={chakraVariant}
106	      size={size}
107	      width={props.fullWidth ? '100%' : undefined}
108	      style={style}
109	      sx={sx}
110	    >
111	      {props.iconLeading && (
112	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
113	          {props.iconLeading}
114	        </chakra.span>
115	      )}
116	      <chakra.span __css={labelStyle}>{label}</chakra.span>
117	      {props.iconTrailing && (
118	        <chakra.span aria-hidden={true} display="flex" alignItems="center" justifyContent="center" flexShrink={0}>
119	          {props.iconTrailing}
120	        </chakra.span>
121	      )}
122	    </ChakraButton>
123	  );
124	};
