const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const BASE = 'http://localhost:6006/iframe.html';
const BREAKPOINTS = [
  { name: 'mobile', width: 390, height: 844 },
  { name: 'tablet', width: 834, height: 1112 },
  { name: 'desktop', width: 1440, height: 900 },
];

const MISMATCH_STORIES = [
  'layout-zimmcountrylanguagemismatch--location',
  'layout-zimmcountrylanguagemismatch--language',
  'layout-zimmcountrylanguagemismatch--language-detected-italian',
  'layout-zimmcountrylanguagemismatch--language-detected-spanish',
  'layout-zimmcountrylanguagemismatch--language-detected-english',
];

const PROMPT_STORIES = ['layout-zimmlanguageprompt--eligible', 'layout-zimmlanguageprompt--suppressed'];

function rectOf(el) {
  if (!el) return null;
  const r = el.getBoundingClientRect();
  return { x: r.x, y: r.y, width: r.width, height: r.height, top: r.top, bottom: r.bottom, left: r.left, right: r.right };
}

async function measureMismatch(page) {
  return page.evaluate(() => {
    function rect(el) {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: r.x, y: r.y, width: r.width, height: r.height, top: r.top, bottom: r.bottom, left: r.left, right: r.right };
    }
    const dialog = document.querySelector('[role="dialog"]');
    if (!dialog) {
      return {
        dialogFound: false,
        scrollWidth: document.documentElement.scrollWidth,
        innerWidth: window.innerWidth,
      };
    }
    const headerRow = dialog.children[0] || null;
    const root = dialog.children[1] || null;
    const contentBlock = root ? root.children[0] : null;
    const buttonGroup = root ? root.children[1] : null;
    const heading = contentBlock ? contentBlock.querySelector('h2') : null;
    const body = contentBlock ? contentBlock.querySelector('p') : null;
    const buttons = buttonGroup ? Array.from(buttonGroup.querySelectorAll('button')) : [];
    const closeBtn = headerRow ? headerRow.querySelector('button') : null;

    const buttonDetails = buttons.map((btn) => {
      const span = btn.querySelector('span');
      const btnRect = btn.getBoundingClientRect();
      const spanRect = span ? span.getBoundingClientRect() : null;
      return {
        text: btn.textContent,
        rect: rect(btn),
        scrollWidth: btn.scrollWidth,
        clientWidth: btn.clientWidth,
        labelRect: rect(span),
        labelScrollWidth: span ? span.scrollWidth : null,
        whiteSpace: span ? getComputedStyle(span).whiteSpace : null,
        btnOverflowHidden: getComputedStyle(btn).overflow,
        overflowsHorizontally: span ? spanRect.width > btnRect.width : null,
        overflowsBySpanScroll: span ? span.scrollWidth > btn.clientWidth : null,
      };
    });

    const rootStyle = root ? getComputedStyle(root) : null;
    const contentStyle = contentBlock ? getComputedStyle(contentBlock) : null;

    return {
      dialogFound: true,
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: window.innerWidth,
      hasHorizontalOverflow: document.documentElement.scrollWidth > window.innerWidth,
      dialogRect: rect(dialog),
      headerRowRect: rect(headerRow),
      closeButtonRect: rect(closeBtn),
      rootRect: rect(root),
      rootPadding: rootStyle
        ? { top: rootStyle.paddingTop, right: rootStyle.paddingRight, bottom: rootStyle.paddingBottom, left: rootStyle.paddingLeft }
        : null,
      rootGap: rootStyle ? rootStyle.rowGap || rootStyle.gap : null,
      contentGap: contentStyle ? contentStyle.rowGap || contentStyle.gap : null,
      contentBlockRect: rect(contentBlock),
      buttonGroupRect: rect(buttonGroup),
      headingRect: rect(heading),
      headingText: heading ? heading.textContent : null,
      headingScrollWidth: heading ? heading.scrollWidth : null,
      headingClientWidth: heading ? heading.clientWidth : null,
      bodyRect: rect(body),
      bodyText: body ? body.textContent : null,
      bodyScrollWidth: body ? body.scrollWidth : null,
      bodyClientWidth: body ? body.clientWidth : null,
      buttons: buttonDetails,
    };
  });
}

async function measurePrompt(page) {
  return page.evaluate(() => {
    const dialog = document.querySelector('[role="dialog"]');
    return {
      dialogFound: !!dialog,
      bodyText: dialog ? dialog.textContent : null,
      scrollWidth: document.documentElement.scrollWidth,
      innerWidth: window.innerWidth,
    };
  });
}

(async () => {
  const browser = await chromium.launch();
  const results = { mismatch: [], prompt: [] };

  for (const story of MISMATCH_STORIES) {
    for (const bp of BREAKPOINTS) {
      const page = await browser.newPage({ viewport: { width: bp.width, height: bp.height } });
      const url = `${BASE}?id=${story}&viewMode=story`;
      try {
        await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
        await page.waitForSelector('[role="dialog"]', { timeout: 5000 }).catch(() => {});
        await page.waitForTimeout(350); // let slide-in transition (300ms) settle
        const data = await measureMismatch(page);
        results.mismatch.push({ story, breakpoint: bp.name, viewportWidth: bp.width, viewportHeight: bp.height, ...data });
      } catch (err) {
        results.mismatch.push({ story, breakpoint: bp.name, viewportWidth: bp.width, error: String(err) });
      } finally {
        await page.close();
      }
    }
  }

  for (const story of PROMPT_STORIES) {
    for (const bp of [BREAKPOINTS[0], BREAKPOINTS[2]]) {
      const page = await browser.newPage({ viewport: { width: bp.width, height: bp.height } });
      const url = `${BASE}?id=${story}&viewMode=story`;
      try {
        await page.goto(url, { waitUntil: 'networkidle', timeout: 30000 });
        await page.waitForTimeout(350);
        const data = await measurePrompt(page);
        results.prompt.push({ story, breakpoint: bp.name, viewportWidth: bp.width, ...data });
      } catch (err) {
        results.prompt.push({ story, breakpoint: bp.name, viewportWidth: bp.width, error: String(err) });
      } finally {
        await page.close();
      }
    }
  }

  await browser.close();
  console.log(JSON.stringify(results, null, 2));
})();

