    root = m.get('rootRect') or {}
    content = m.get('contentBlockRect') or {}
    bg = m.get('buttonGroupRect') or {}
    heading = m.get('headingRect') or {}
    body = m.get('bodyRect') or {}
    btns = m.get('buttons') or []

    heading_body_gap = (body.get('top',0) - heading.get('bottom',0)) if heading and body else None
    content_bg_gap = (bg.get('top',0) - content.get('bottom',0)) if content and bg else None
    btn_gap = None
